from collections import defaultdict

def count_right_triangles(N, points):
    # Create dictionaries to store points by their x and y coordinates
    x_points = defaultdict(list)
    y_points = defaultdict(list)

    # Populate the dictionaries
    for i, (x, y) in enumerate(points):
        x_points[x].append(i)
        y_points[y].append(i)

    count = 0

    # Check for right triangles using the x-coordinate dictionary
    for x in x_points:
        for i in range(len(x_points[x])):
            for j in range(i + 1, len(x_points[x])):
                p1, p2 = x_points[x][i], x_points[x][j]
                # Find the third point with the same x-coordinate but different y-coordinate
                for k in y_points[points[p1][1]]:
                    if k != p1 and k != p2:
                        count += 1

    # Check for right triangles using the y-coordinate dictionary
    for y in y_points:
        for i in range(len(y_points[y])):
            for j in range(i + 1, len(y_points[y])):
                p1, p2 = y_points[y][i], y_points[y][j]
                # Find the third point with the same y-coordinate but different x-coordinate
                for k in x_points[points[p1][0]]:
                    if k != p1 and k != p2:
                        count += 1

    return count

