def count_right_triangles(N, points):
    x_count = defaultdict(int)
    y_count = defaultdict(int)

    for x, y in points:
        x_count[x] += 1
        y_count[y] += 1

    result = 0

    for x, count_x in x_count.items():
        for y, count_y in y_count.items():
            if count_x > 1 and count_y > 1:
                result += count_x * count_y

    return result

